export function repository(){const rows=[];let n=20;const match=(d,q)=>Object.entries(q).every(([k,v])=>k==='hearingDate'||String(d[k])===String(v));class Repo{constructor(fields){Object.assign(this,fields,{_id:String(++n).padStart(24,'0')});}async save(){rows.push(this)}static find(q){const selected=rows.filter(d=>match(d,q));const chain={sort(){return chain},lean:async()=>selected,then(resolve,reject){return Promise.resolve(selected).then(resolve,reject)}};return chain}static async findOne(q){return rows.find(d=>match(d,q))||null}static async findOneAndDelete(q){const i=rows.findIndex(d=>match(d,q));return i<0?null:rows.splice(i,1)[0]}static async findOneAndUpdate(q,u){const d=await this.findOne(q);if(d)Object.assign(d,u.$set);return d}static async insertMany(data){const docs=data.map(d=>new Repo(d));rows.push(...docs);return docs}}return{Repo,rows};}
